:root {
  --blue: #4d8dff;
  --ice: #dfe9ff;
  --navy: #0b1e3f;
}
#stage { background: #01040c; font-family: "Inter", sans-serif; color: #fff; }
.gl { position: absolute; left: 0; top: 0; width: 1080px; height: 1920px; }
.layer { position: absolute; inset: 0; }
.ln { position: absolute; left: 0; width: 1080px; text-align: center; white-space: nowrap; line-height: 1; display: none; }
.title { font: 700 62px/1 "Inter"; letter-spacing: 0.16em; text-shadow: 0 0 22px rgba(120, 170, 255, 0.55), 0 0 60px rgba(70, 130, 255, 0.35); }
.name { font: 800 100px/1 "Inter"; letter-spacing: -0.035em; text-shadow: 0 0 28px rgba(120, 170, 255, 0.45); }
.head { font: 800 96px/1 "Inter"; letter-spacing: -0.035em; text-shadow: 0 0 26px rgba(120, 170, 255, 0.4); }
.blue { color: var(--blue); text-shadow: 0 0 24px rgba(77, 141, 255, 0.85), 0 0 70px rgba(77, 141, 255, 0.45); }
.label { font: 600 30px/1 "Inter"; letter-spacing: 0.32em; color: var(--ice); opacity: 0.9; }
.handle { font: 500 32px/1 "Inter"; letter-spacing: 0.04em; color: rgba(223, 233, 255, 0.62); }
.kanji { position: absolute; display: none; writing-mode: vertical-rl; font: 600 52px/1 "Hiragino Mincho ProN", serif; letter-spacing: 0.3em; color: rgba(150, 190, 255, 0.92); text-shadow: 0 0 18px rgba(77, 141, 255, 0.6); }
.kanji.navy { color: #2d5bd8; text-shadow: none; font-size: 54px; }
/* The call to action as Liquid Glass: the frame behind blurred and brightened, a light rim. */
.cta { position: absolute; display: none; left: 210px; width: 660px; top: 1282px; height: 92px; border-radius: 46px; text-align: center; font: 700 30px/92px "Inter"; letter-spacing: 0.16em; color: #fff;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.22), rgba(255, 255, 255, 0.06)); backdrop-filter: blur(18px) saturate(1.8) brightness(1.15); -webkit-backdrop-filter: blur(18px) saturate(1.8) brightness(1.15);
  box-shadow: inset 0 1.5px 0 rgba(255, 255, 255, 0.75), inset 0 -1px 0 rgba(255, 255, 255, 0.25), inset 0 0 0 1px rgba(255, 255, 255, 0.18), 0 18px 50px rgba(0, 0, 0, 0.45), 0 0 40px rgba(77, 141, 255, 0.35); }
.vignette { position: absolute; inset: 0; background: radial-gradient(ellipse 85% 70% at 50% 48%, rgba(0, 0, 0, 0) 55%, rgba(0, 4, 14, 0.5) 100%); pointer-events: none; }
.grain { position: absolute; inset: 0; opacity: 0.035; pointer-events: none; }

