// ---------------------------------------------------------------------------------------
// iPhone 17 Pro in Silver, at real scale (1 unit = 100 mm): an aluminium unibody with contoured
// edges, flush front glass, the full-width camera plateau with three lenses, flash and LiDAR, the
// Ceramic Shield window on the back, the buttons and Camera Control, antenna bands, port, grilles.
const MM = 0.01;
const PW = 71.9 * MM;
const PH = 150.0 * MM;
const PD = 8.75 * MM;
const BODY_R = 20.6 * MM;
const UI = { W: 402, H: 874 };
const DISP = { w: PW - 5.3 * MM, h: PH - 5.3 * MM };

// A rounded rectangle with continuous (superellipse) corners, counter-clockwise, with outward
// normals and arc length.
function outline(w, h, r, n = 3.4, cseg = 40, lseg = 8) {
  const e = 2 / n;
  const C = [[w / 2 - r, h / 2 - r], [-(w / 2 - r), h / 2 - r], [-(w / 2 - r), -(h / 2 - r)], [w / 2 - r, -(h / 2 - r)]];
  const at = (q, th) => {
    const c = Math.cos(th);
    const s = Math.sin(th);
    return [C[q][0] + r * Math.sign(c) * Math.abs(c) ** e, C[q][1] + r * Math.sign(s) * Math.abs(s) ** e];
  };
  const P = [];
  for (let q = 0; q < 4; q++) {
    for (let i = 0; i <= cseg; i++) P.push(at(q, ((q + i / cseg) * Math.PI) / 2));
    const a = P[P.length - 1];
    const b = at((q + 1) % 4, (((q + 1) % 4) * Math.PI) / 2);
    for (let k = 1; k < lseg; k++) P.push([lerp(a[0], b[0], k / lseg), lerp(a[1], b[1], k / lseg)]);
  }
  const N = [];
  const U = [0];
  for (let i = 0; i < P.length; i++) {
    const p0 = P[(i - 1 + P.length) % P.length];
    const p1 = P[(i + 1) % P.length];
    const l = Math.hypot(p1[0] - p0[0], p1[1] - p0[1]);
    N.push([(p1[1] - p0[1]) / l, -(p1[0] - p0[0]) / l]);
    if (i) U.push(U[i - 1] + Math.hypot(P[i][0] - P[i - 1][0], P[i][1] - P[i - 1][1]));
  }
  const total = U[U.length - 1] + Math.hypot(P[0][0] - P[P.length - 1][0], P[0][1] - P[P.length - 1][1]);
  return { P, N, U, total };
}
const offsetPts = (ol, d) => ol.P.map(([x, y], i) => [x + ol.N[i][0] * d, y + ol.N[i][1] * d]);
// The plateau's outline, counter-clockwise: continuous top corners like the body's, a straight
// bottom edge with small round corners; bottom edge on y = 0.
function plateauShape(w, h, rTop, rBot, n = 3.4, seg = 40) {
  const e = 2 / n;
  const P = [[w / 2, rBot]];
  for (let i = 0; i <= seg; i++) {
    const th = (i / seg) * Math.PI;
    const c = Math.cos(th);
    const s = Math.sin(th);
    const cx = c >= 0 ? w / 2 - rTop : -(w / 2 - rTop);
    P.push([cx + rTop * Math.sign(c) * Math.abs(c) ** e, h - rTop + rTop * Math.abs(s) ** e]);
    if (i === seg / 2) P.push([-(w / 2 - rTop), h]);
  }
  for (let i = 1; i <= 12; i++) {
    const a = Math.PI + (i / 12) * (Math.PI / 2);
    P.push([-w / 2 + rBot + rBot * Math.cos(a), rBot + rBot * Math.sin(a)]);
  }
  for (let i = 0; i < 12; i++) {
    const a = 1.5 * Math.PI + (i / 12) * (Math.PI / 2);
    P.push([w / 2 - rBot + rBot * Math.cos(a), rBot + rBot * Math.sin(a)]);
  }
  return P;
}

// Sweeps a profile [(n, z)] (n: outward offset, z: depth, both in units) along an outline.
function sweepGeo(ol, prof) {
  const NQ = prof.length;
  const pn = [];
  const pv = [0];
  for (let j = 0; j < NQ; j++) {
    const a = prof[Math.max(0, j - 1)];
    const b = prof[Math.min(NQ - 1, j + 1)];
    const dn = b[0] - a[0];
    const dz = b[1] - a[1];
    const l = Math.hypot(dn, dz);
    pn.push([-dz / l, dn / l]);
    if (j) pv.push(pv[j - 1] + Math.hypot(prof[j][0] - prof[j - 1][0], prof[j][1] - prof[j - 1][1]));
  }
  const NPc = ol.P.length + 1;
  const pos = new Float32Array(NPc * NQ * 3);
  const nor = new Float32Array(NPc * NQ * 3);
  const uv = new Float32Array(NPc * NQ * 2);
  for (let i = 0; i < NPc; i++) {
    const k = i % ol.P.length;
    const [px, py] = ol.P[k];
    const [nx, ny] = ol.N[k];
    const u = i === ol.P.length ? 1 : ol.U[k] / ol.total;
    for (let j = 0; j < NQ; j++) {
      const o = i * NQ + j;
      const [n, z] = prof[j];
      pos.set([px + nx * n, py + ny * n, z], o * 3);
      nor.set([nx * pn[j][0], ny * pn[j][0], pn[j][1]], o * 3);
      uv.set([u, pv[j] / pv[NQ - 1]], o * 2);
    }
  }
  const idx = [];
  for (let i = 0; i < NPc - 1; i++) {
    for (let j = 0; j < NQ - 1; j++) {
      const a = i * NQ + j;
      const b = (i + 1) * NQ + j;
