// Real 3D letters: Bebas Neue's outlines read from the TrueType file, extruded with a bevel.
async function loadFont(url) {
  const buf = await (await fetch(url)).arrayBuffer();
  const dv = new DataView(buf);
  const tables = {};
  for (let i = 0; i < dv.getUint16(4); i++) {
    const o = 12 + i * 16;
    const tag = String.fromCharCode(dv.getUint8(o), dv.getUint8(o + 1), dv.getUint8(o + 2), dv.getUint8(o + 3));
    tables[tag] = dv.getUint32(o + 8);
  }
  const upm = dv.getUint16(tables.head + 18);
  const longLoca = dv.getInt16(tables.head + 50) === 1;
  const numHM = dv.getUint16(tables.hhea + 34);
  const advance = (g) => dv.getUint16(tables.hmtx + 4 * Math.min(g, numHM - 1));
  const loca = (g) => (longLoca ? dv.getUint32(tables.loca + g * 4) : dv.getUint16(tables.loca + g * 2) * 2);
  let sub = 0;
  for (let i = 0; i < dv.getUint16(tables.cmap + 2); i++) {
    const pid = dv.getUint16(tables.cmap + 4 + i * 8);
    const eid = dv.getUint16(tables.cmap + 6 + i * 8);
    const off = tables.cmap + dv.getUint32(tables.cmap + 8 + i * 8);
    if (dv.getUint16(off) === 4 && ((pid === 3 && eid === 1) || pid === 0)) sub = off;
  }
  const segs = dv.getUint16(sub + 6) / 2;
  const endO = sub + 14;
  const startO = endO + segs * 2 + 2;
  const deltaO = startO + segs * 2;
  const rangeO = deltaO + segs * 2;
  const glyphIndex = (code) => {
    for (let i = 0; i < segs; i++) {
      if (code > dv.getUint16(endO + i * 2)) continue;
      const start = dv.getUint16(startO + i * 2);
      if (code < start) return 0;
      const delta = dv.getInt16(deltaO + i * 2);
      const ro = dv.getUint16(rangeO + i * 2);
      if (!ro) return (code + delta) & 0xffff;
      const gi = dv.getUint16(rangeO + i * 2 + ro + (code - start) * 2);
      return gi ? (gi + delta) & 0xffff : 0;
    }
    return 0;
  };
  const contours = (g) => {
    const o = loca(g);
    if (o === loca(g + 1)) return [];
    const p = tables.glyf + o;
    const nc = dv.getInt16(p);
    if (nc < 0) {
      const out = [];
      let q = p + 10;
      for (let more = true; more; ) {
        const fl = dv.getUint16(q);
        const gi = dv.getUint16(q + 2);
        q += 4;
        let dx;
        let dy;
        if (fl & 1) {
          dx = dv.getInt16(q);
          dy = dv.getInt16(q + 2);
          q += 4;
        } else {
          dx = dv.getInt8(q);
          dy = dv.getInt8(q + 1);
          q += 2;
        }
        let [a, b, c, d] = [1, 0, 0, 1];
        if (fl & 8) {
          a = d = dv.getInt16(q) / 16384;
          q += 2;
        } else if (fl & 0x40) {
          a = dv.getInt16(q) / 16384;
          d = dv.getInt16(q + 2) / 16384;
          q += 4;
        } else if (fl & 0x80) {
          [a, b, c, d] = [0, 2, 4, 6].map((k) => dv.getInt16(q + k) / 16384);
          q += 8;
        }
        for (const ct of contours(gi)) out.push(ct.map((pt) => ({ x: a * pt.x + c * pt.y + dx, y: b * pt.x + d * pt.y + dy, on: pt.on })));
        more = !!(fl & 0x20);
      }
      return out;
    }
    const ends = [];
    for (let i = 0; i < nc; i++) ends.push(dv.getUint16(p + 10 + i * 2));
    const n = ends[nc - 1] + 1;
    let q = p + 10 + nc * 2;
    q += 2 + dv.getUint16(q);
    const flags = [];
    while (flags.length < n) {
      const f = dv.getUint8(q++);
      flags.push(f);
      if (f & 8) for (let r = dv.getUint8(q++); r > 0; r--) flags.push(f);
    }
    const coord = (short, same) => {
      const out = [];
      let v = 0;
      for (const f of flags) {
        if (f & short) {
          const d = dv.getUint8(q++);
          v += f & same ? d : -d;
        } else if (!(f & same)) {
          v += dv.getInt16(q);
          q += 2;
        }
        out.push(v);
      }
      return out;
    };
    const xs = coord(2, 16);
    const ys = coord(4, 32);
    const out = [];
    let s = 0;
    for (const e of ends) {
      const c = [];
      for (let i = s; i <= e; i++) c.push({ x: xs[i], y: ys[i], on: !!(flags[i] & 1) });
      out.push(c);
      s = e + 1;
    }
    return out;
  };
  return { upm, glyphIndex, advance, contours };
}

// The shapes of one character, in em units (cap height 0.7 for Bebas Neue).
function glyphShapes(font, ch) {
  const gi = font.glyphIndex(ch.codePointAt(0));
  const k = 1 / font.upm;
  const sp = new THREE.ShapePath();
  for (const c of font.contours(gi)) {
    let start = c.findIndex((p) => p.on);
    let pts = c;
    if (start < 0) {
      pts = [{ x: (c[0].x + c[1].x) / 2, y: (c[0].y + c[1].y) / 2, on: true }, ...c.slice(1), c[0]];
      start = 0;
    }
    const n = pts.length;
    const p0 = pts[start];
    sp.moveTo(p0.x * k, p0.y * k);
    let ctrl = null;
    for (let i = 1; i <= n; i++) {
      const p = pts[(start + i) % n];
      if (p.on) {
        if (ctrl) sp.quadraticCurveTo(ctrl.x * k, ctrl.y * k, p.x * k, p.y * k);
        else sp.lineTo(p.x * k, p.y * k);
        ctrl = null;
      } else {
        if (ctrl) {
          const mx = (ctrl.x + p.x) / 2;
          const my = (ctrl.y + p.y) / 2;
          sp.quadraticCurveTo(ctrl.x * k, ctrl.y * k, mx * k, my * k);
        }
        ctrl = p;
      }
    }
  }
  return { shapes: sp.toShapes(false), advance: font.advance(gi) * k };
}

// A word as one group of letter meshes (each letter its own pivot at its centre), centred on 0,
// `size` units per em, extruded `depth` (in em), bevelled.
function text3D(font, text, size, mats, { depth = 0.16, bevel = 0.018, track = 0 } = {}) {
  const g = new THREE.Group();
  const letters = [];
  let pen = 0;
  for (const ch of text) {
    const { shapes, advance } = glyphShapes(font, ch);
    if (shapes.length) {
      const geo = new THREE.ExtrudeGeometry(shapes, { depth, bevelEnabled: true, bevelThickness: bevel, bevelSize: bevel * 0.8, bevelSegments: 5, curveSegments: 10 });
      geo.computeBoundingBox();
      const bb = geo.boundingBox;
      const cx = (bb.min.x + bb.max.x) / 2;
      const cy = 0.35;
      geo.translate(-cx, -cy, -depth / 2);
      const m = new THREE.Mesh(geo, mats);
      const pivot = new THREE.Group();
      pivot.add(m);
      pivot.position.set((pen + cx) * size, 0, 0);
      pivot.scale.setScalar(size);
      pivot.userData = { ch, home: pivot.position.clone() };
      g.add(pivot);
      letters.push(pivot);
    }
    pen += advance + track;
  }
  const w = (pen - track) * size;
  letters.forEach((l) => {
    l.position.x -= w / 2;
    l.userData.home.x -= w / 2;
  });
  return { g, letters, width: w };
}
