// Liquid Glass: real refraction (transmission) with a little dispersion and a clear coat for the
// rim light. Shapes have soft, thick rounded edges, so they bend what is behind them most at
// their borders, like Apple's material.
function glassMat(extra = {}) {
  return new THREE.MeshPhysicalMaterial({
    color: 0xffffff, metalness: 0, roughness: 0.03, transmission: 1, thickness: 0.09, ior: 1.45,
    dispersion: 0.35, clearcoat: 1, clearcoatRoughness: 0.02, specularIntensity: 1,
    attenuationColor: new THREE.Color("#e6eeff"), attenuationDistance: 1.4, ...extra,
  });
}
// A slab: depth d, corner and edge radius r (up to d / 2 for a fully rounded edge).
const glassSlab = (w, h, d, r, mat) => new THREE.Mesh(new O.RoundedBoxGeometry(w, h, d, 12, r), mat);
// A disc of radius R and thickness T with a fully rounded rim and a domed face, facing +z.
function glassDiscGeo(R, T, dome) {
  const rr = T / 2;
  const c = R - rr;
  const pts = [];
  for (let i = 0; i <= 30; i++) pts.push(new THREE.Vector2((c * i) / 30, -rr));
  for (let i = 1; i <= 28; i++) {
    const a = -Math.PI / 2 + (i / 28) * Math.PI;
    pts.push(new THREE.Vector2(c + rr * Math.cos(a), rr * Math.sin(a)));
  }
  for (let i = 1; i <= 40; i++) {
    const x = c * (1 - i / 40);
    pts.push(new THREE.Vector2(x, rr + dome * (1 - (x / c) ** 2)));
  }
  const g = new THREE.LatheGeometry(pts, 160);
  g.rotateX(Math.PI / 2);
  return g;
}
// A ring of light: HDR colour, so bloom makes it glow.
function glowRing(R, tube, rgb) {
  return new THREE.Mesh(new THREE.TorusGeometry(R, tube, 12, 320), new THREE.MeshBasicMaterial({ color: new THREE.Color(...rgb), transparent: true, depthWrite: false, blending: THREE.AdditiveBlending }));
}
// Text on a plane, `h` units tall. hash: dithered alpha, so glass in front can refract it.
function textPlane(text, font, h, color, { ls = 0, pad = 24, hash = false, glow = 0 } = {}) {
  const probe = canvas(10, 10).getContext("2d");
  probe.font = font;
  probe.letterSpacing = `${ls}px`;
  const m = probe.measureText(text);
  const asc = m.actualBoundingBoxAscent;
  const desc = m.actualBoundingBoxDescent;
  const c = canvas(Math.ceil(m.width + pad * 2), Math.ceil(asc + desc + pad * 2));
  const x = c.getContext("2d");
  x.font = font;
  x.letterSpacing = `${ls}px`;
  x.fillStyle = "#fff";
  if (glow) {
    // A soft halo under a crisp letter.
    x.shadowColor = "rgba(255,255,255,0.75)";
    x.shadowBlur = glow;
    x.globalAlpha = 0.6;
    x.fillText(text, pad, pad + asc);
    x.shadowBlur = 0;
    x.globalAlpha = 1;
  }
  x.fillText(text, pad, pad + asc);
  const mat = new THREE.MeshBasicMaterial({ map: tex(c), color, transparent: !hash, alphaHash: hash, depthWrite: hash, side: THREE.DoubleSide });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry((h * c.width) / c.height, h), mat);
  mesh.userData.aspect = c.width / c.height;
  return mesh;
}
