// A photo on a liquid glass card: the glass is bigger than the photo, so its thick rounded rim
// bends the picture's edges.
function glassCard(img, w, h, { depth = 0.12, r = 0.06, mat } = {}) {
  const g = new THREE.Group();
  const c = canvas(Math.round(600 * (w / h)), 600);
  cover(c.getContext("2d"), img, 0, 0, c.width, c.height);
  const photo = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({ map: tex(c) }));
  const slab = glassSlab(w + 2.2 * r, h + 2.2 * r, depth, r, mat ?? O.glass);
