}
// A capsule of glass (a stadium extruded with a fully rounded edge), centred, facing +z.
function glassPill(w, h, d, mat) {
  const r = h / 2 - d / 2;
  const s = new THREE.Shape();
  const hw = w / 2 - d / 2;
  s.absarc(hw - r, 0, r, -Math.PI / 2, Math.PI / 2, false);
  s.absarc(-(hw - r), 0, r, Math.PI / 2, (3 * Math.PI) / 2, false);
  const geo = new THREE.ExtrudeGeometry(s, { depth: 0.002, bevelEnabled: true, bevelThickness: d / 2, bevelSize: d / 2, bevelSegments: 10, curveSegments: 48 });
  geo.translate(0, 0, -0.001);
  return new THREE.Mesh(geo, mat);
