  const x = easeIn(span(t, out, out + outDur));
  const o = clamp(e * 1.4) * (1 - x);
  n.style.display = o > 0.002 ? "block" : "none";
  if (o <= 0.002) return;
  const b = 14 * (1 - e) + 12 * x;
