function hideAll() {
  O.phone.g.visible = false;
  O.lift.forEach((c) => (c.visible = false));
  O.em.g.visible = false;
  O.founder.visible = false;
  Object.values(O.field).forEach((m) => (m.visible = false));
  Object.values(O.glow).forEach((m) => (m.visible = false));
  O.carousel.forEach((c) => (c.visible = false));
  O.pills.forEach((p) => (p.visible = false));
  O.plus.g.visible = false;
  for (const k of ["pg", "fd", "gm", "wk", "end"]) H[k].r.style.display = "none";
  scene.background = O.bgNavy;
  scene.environmentRotation.set(0, 0, 0);
  bokeh.enabled = false;
  bloom.strength = 0.7;
}
function orbs(t, on = true) {
  O.orbs.forEach((m) => {
    m.visible = on;
    if (!on) return;
    const u = m.userData;
    m.position.copy(u.home);
    m.position.y += Math.sin(t * u.v * 6 + u.home.x) * 0.25 + t * u.v;
    m.scale.setScalar(u.s);
    m.quaternion.copy(camera.quaternion);
  });
}
function emblemRings(t, base = 1) {
  const E = O.em;
  E.orbit[0].rotation.z = t * 0.6;
  E.orbit[1].rotation.z = -t * 0.45;
  const k = base * (1 + 0.5 * pulse(t, 8.59, 5) + 0.5 * pulse(t, 9.39, 5) + 0.8 * pulse(t, T.hit, 4));
  E.orbit.forEach((r, i) => r.material.opacity = Math.min(1, k) * (i ? 0.75 : 1));
}

// 1. The phone tumbles in from the dark, turns to his profile; the camera skims the screen as
//    his photos lift off in glass; it glides to his picture, which rises; on the drop it flips
//    into the Platinum Game emblem. s1State(t) is also where scene 2 starts from.
function s1State(t) {
  const P = O.phone;
  const come = expoOut(span(t, 0, 2.6));
  const turn = cubicInOut(span(t, T.turn, 3.45));
  P.g.position.set(0, lerp(-0.4, 0, come), lerp(-13, 0, come));
  const ry = lerp(lerp(2.3, Math.PI - 0.42, easeOut(span(t, 0, T.turn))), -0.32, turn) + 0.05 * span(t, 3.45, T.drop);
  P.g.rotation.set(lerp(lerp(-0.55, 0.12, come), 0.08, turn), ry, lerp(lerp(0.45, -0.04, come), 0, turn));
  P.g.updateMatrixWorld(true);
  const L = (x, y, z) => P.g.localToWorld(V(x, y, z));
  const wide = { pos: V(0, 0.05, lerp(5.2, 4.6, turn)), tgt: V(0, 0, 0) };
  const low = { pos: L(0.06, -0.92, 0.42), tgt: L(0, 0.2, 0.04) };
  const av = P.avatarLocal;
  const close = (d) => ({ pos: L(av.x + 0.1 * d, av.y - 0.32 * d, av.z + d), tgt: L(av.x, av.y, av.z) });
  let cam;
  if (t < T.swoop) cam = wide;
  else if (t < T.glide) {
    const q = cubicInOut(span(t, T.swoop, 4.6));
    cam = { pos: wide.pos.clone().lerp(low.pos, q), tgt: wide.tgt.clone().lerp(low.tgt, q) };
  } else {
    const q = cubicInOut(span(t, T.glide, T.pre));
    const c = close(lerp(0.75, 0.48, q) - 0.16 * cubicIn(span(t, T.pre, T.drop)));
    cam = { pos: low.pos.clone().lerp(c.pos, q), tgt: low.tgt.clone().lerp(c.tgt, q) };
  }
  cam.up = V(0, 1, 0).lerp(V(0, 1, 0).applyQuaternion(P.g.quaternion), cubicInOut(span(t, T.swoop, 4.6))).normalize();
  const lift = easeInOut(span(t, 5.8, T.drop));
  const em = { pos: L(av.x, av.y, av.z + 0.004 + 0.07 * lift), quat: P.g.quaternion.clone(), s: ((44 / UI0.W) * DISP.w) / 0.42 };
  return { cam, em, L };
}
function s1(t) {
  const P = O.phone;
  P.g.visible = true;
  setScreen("jk", easeOut(span(t, T.wake, T.wake + 0.45)));
  scene.environmentRotation.set(0, lerp(-0.8, 0.3, span(t, 0, T.drop)), 0);
  const { cam, em } = s1State(t);
  O.lift.forEach((c, i) => {
    const a = T.cards + i * 0.14;
    const e = backOut(span(t, a, a + 0.6), 1.2);
    const away = easeIn(span(t, 5.9 + i * 0.08, 6.6 + i * 0.08));
    c.visible = t >= a && away < 1;
    c.position.copy(c.userData.home);
    c.position.z += 0.012 + 0.2 * e + 0.05 * i * e + 1.6 * away;
    c.position.y += 0.06 * e + 0.5 * away;
    c.rotation.set(-0.35 * e, (i - 1) * 0.16 * e, 0);
  });
  lookAt(cam.pos, cam.tgt, cam.up);
  if (t >= T.glide) {
    bokeh.enabled = true;
    bokeh.uniforms.focus.value = cam.pos.distanceTo(cam.tgt);
    bokeh.uniforms.aperture.value = 0.035;
    bokeh.uniforms.maxblur.value = 0.006;
  }
  if (t >= 5.8) {
    const E = O.em;
    E.g.visible = true;
    E.g.position.copy(em.pos);
    E.g.quaternion.copy(em.quat);
    E.g.scale.setScalar(em.s);
    E.coin.rotation.set(0, 0, 0);
    E.orbit.forEach((r) => (r.visible = false));
    E.burst.forEach((r) => (r.visible = false));
  }
}

// 2. The emblem in the light: Platinum Game. Then the founder on a glass card.
function s2(t) {
  const E = O.em;
  scene.environmentRotation.set(0, lerp(0.3, -0.5, span(t, T.drop, T.end)), 0);
  if (t < T.founder) {
    // The phone falls away behind the drop.
    const fall = cubicIn(span(t, T.drop, 7.9));
    if (fall < 1) {
      const P = O.phone;
      P.g.visible = true;
      setScreen("jk", 1);
      P.g.position.set(0, -2.2 * fall, -1.5 * fall);
      P.g.rotation.set(0.08 + 1.2 * fall, -0.27 - 0.8 * fall, 0);
    }
    E.g.visible = true;
    const a = expoOut(span(t, T.drop, T.drop + 0.9));
    const s0 = s1State(T.drop);
    const flip = expoOut(span(t, T.drop, T.drop + 0.7)) * Math.PI;
    const out = cubicIn(span(t, T.flip + 0.1, T.founder));
    E.g.position.copy(s0.em.pos.clone().lerp(V(0, 0.2, 0), a));
    E.g.position.z += 3.4 * out;
    E.g.quaternion.copy(s0.em.quat.clone().slerp(new THREE.Quaternion(), a));
    E.g.scale.setScalar(lerp(s0.em.s, 0.8, a));
    E.coin.rotation.set(0.12 * Math.sin(t * 0.9), flip + 0.3 * Math.sin((t - T.drop) * 0.8) + Math.PI * expoOut(span(t, T.flip, T.flip + 0.6)), 0);
    E.orbit.forEach((r) => (r.visible = true));
    emblemRings(t, a);
    E.burst.forEach((r, i) => {
      const q = span(t, T.drop + i * 0.09, T.drop + 0.9 + i * 0.09);
      r.visible = q > 0 && q < 1;
      r.scale.setScalar(1 + 2.6 * expoOut(q));
      r.material.opacity = (1 - q) * 0.9;
    });
    bloom.strength = 0.7 + 0.8 * pulse(t, T.drop, 5);
    const c = expoOut(span(t, T.drop, T.drop + 1.0));
    lookAt(s0.cam.pos.clone().lerp(V(0.02, 0.12, 4.2), c), s0.cam.tgt.clone().lerp(V(0, 0.12, 0), c), s0.cam.up.clone().lerp(V(0, 1, 0), c).normalize());
    H.pg.r.style.display = "block";
    showLine(H.pg.name, t, T.bar1, { out: T.flip - 0.05 });
    showLine(H.pg.kanji, t, T.bar1 + 0.25, { out: T.flip - 0.05 });
    return;
  }
  // The founder.
  const F = O.founder;
  F.visible = true;
  const a = expoOut(span(t, T.founder, T.founder + 0.9));
  const out = cubicIn(span(t, T.out2, T.field));
  F.position.set(lerp(-2.4, 0, a) + 2.6 * out, 0.47, 0);
  F.rotation.set(0.05, lerp(0.9, -0.22, a) + 0.3 * span(t, T.founder + 0.9, T.out2) - 1.4 * out, 0);
  lookAt(V(0, 0.18, 4.3), V(0, 0.18, 0));
  H.fd.r.style.display = "block";
  showLine(H.fd.name, t, 11.39, { out: T.out2 });
  showLine(H.fd.role, t, 11.79, { out: T.out2 + 0.05 });
  showLine(H.fd.kanji, t, 11.79, { out: T.out2 });
}

// 3. Life is a game: navy words on a pearl field, a glass capsule sliding over GAME; then STOP
//    POSTING / START POSITIONING glowing in the dark.
function s3(t) {
  if (t < T.dark) {
    scene.background = O.bgPearl;
    const F = O.field;
    const enter = (m, at, x, y, { spin = 1.1 } = {}) => {
      const e = expoOut(span(t, at, at + 0.55));
      m.visible = t >= at;
      m.position.set(x, y, -0.6 * (1 - e));
      m.rotation.set(spin * (1 - e), 0, 0);
      m.material.opacity = 1;
    };
    enter(F.life, T.field, 0, 0.66);
    enter(F.isa, T.field + 0.4, 0, 0.4);
    enter(F.game, T.game, 0, 0.12, { spin: 0 });
    F.game.scale.setScalar(lerp(1.35, 1, expoOut(span(t, T.game, T.game + 0.4))));
    enter(F.stay, T.stay, 0, -0.42);
    enter(F.three, T.three, 0, -0.62);
    enter(F.ahead, T.ahead, 0, -0.84);
    const cp = cubicInOut(span(t, T.game + 0.15, 16.5));
    F.cap.visible = t >= T.game;
    F.cap.position.set(lerp(-0.9, 0.9, cp), 0.12, 0.26);
    F.cap.rotation.set(0, 0.12 * Math.sin(cp * Math.PI), 0);
    const tilt = cubicInOut(span(t, 15.55, 16.3));
    const ty = lerp(0.38, -0.62, tilt);
    const ang = lerp(-0.12, 0.1, span(t, T.field, T.dark));
    lookAt(V(Math.sin(ang) * 3.3, ty + 0.05, Math.cos(ang) * 3.3), V(0, ty, 0));
    bloom.strength = 0.2;
    H.gm.r.style.display = "block";
    showLine(H.gm.kanji, t, T.ahead + 0.1, { out: T.dark - 0.05 });
    return;
  }
  const G = O.glow;
  const flyIn = (m, at, x, y) => {
    const e = expoOut(span(t, at, at + 0.6));
    const fly = cubicIn(span(t, T.fly + (y < 0 ? 0.12 : 0), T.work));
    m.visible = t >= at && fly < 0.98;
    m.position.set(x, y, -0.9 * (1 - e) + 4.2 * fly);
    m.rotation.set(-1.2 * (1 - e), 0.3 * (1 - e), 0);
  };
  flyIn(G.stop, T.dark, 0, 0.2);
  flyIn(G.start, T.start, -0.15, -0.01);
  flyIn(G.posit, T.posit, 0, -0.2);
  G.stop.material.opacity = 1 - 0.7 * easeInOut(span(t, T.dim, T.dim + 0.4));
  const ang = lerp(0.14, -0.1, span(t, T.dark, T.work));
  lookAt(V(Math.sin(ang) * 3.4, 0.02, Math.cos(ang) * 3.4), V(0, 0, 0));
  bloom.strength = 0.45;
}

// 4. The work: the company's profile on the phone, his series and their posts on glass cards
//    around it, the services on glass capsules, then +100 brands in platinum.
function s4(t) {
  const P = O.phone;
  P.g.visible = true;
  setScreen("co", 1);
  const a = expoOut(span(t, T.work - 0.15, T.work + 0.8));
  const recede = cubicInOut(span(t, T.brands - 0.6, T.brands + 0.1));
  const pillsOut = easeIn(span(t, T.brands - 0.6, T.brands - 0.3));
  const gone = cubicIn(span(t, T.back, T.end));
  P.g.visible = recede < 1;
  P.g.position.set(0, lerp(-1.6, 0, a) - 2.6 * recede, -0.8 * recede);
  P.g.rotation.set(lerp(0.6, 0.06, a), lerp(-1.4, -0.24, a) + 0.36 * span(t, T.work, T.brands), 0);
  scene.environmentRotation.set(0, lerp(-0.6, 0.6, span(t, T.work, T.end)), 0);
  O.carousel.forEach((c, i) => {
    c.visible = true;
    const R = lerp(3.2, 0.95, a) + 1.4 * recede;
    const ang = c.userData.a + 0.42 * (t - T.work);
    c.position.set(Math.sin(ang) * R, c.userData.y + 0.3, Math.cos(ang) * R * 0.75 - 0.2);
    c.rotation.set(0, ang * 0.6, 0);
    c.scale.setScalar(lerp(0.4, 1, a) * (1 - 0.4 * recede) * (1 - gone));
  });
  O.pills.forEach((p, i) => {
    const at = T.pills[i];
    const e = t >= at ? backOut(span(t, at, at + 0.45), 1.7) : 0;
    p.visible = t >= at && pillsOut < 1;
    p.position.set([-0.06, 0.08, -0.03][i], 0.68 - i * 0.24, [0.62, 0.78, 0.7][i]);
    p.scale.setScalar(Math.max(0.001, e) * (1 - pillsOut));
    p.rotation.set(0.1 * (1 - Math.min(1, e)), -0.1 + 0.06 * Math.sin(t * 1.3 + i), 0);
  });
  const N = O.plus;
  if (t >= T.brands - 0.3) {
    N.g.visible = true;
    const f = expoOut(span(t, T.brands - 0.3, T.brands + 0.4));
    const leave = cubicIn(span(t, T.back + 0.3, T.end));
    N.g.position.set(0, 0.3, lerp(-6, 0.7, f) + 3 * leave);
    N.g.rotation.set(0.08, lerp(-1.4, -0.12, f) + 0.25 * span(t, T.brands, T.back) + 2.2 * leave, 0);
  }
  lookAt(V(0, 0.3, 5.2), V(0, 0.3, 0));
  bloom.strength = lerp(0.7, 0.3, recede);
  H.wk.r.style.display = "block";
  showLine(H.wk.l1, t, T.work + 0.2, { out: T.brands - 0.3 });
  showLine(H.wk.l2, t, T.work + 0.4, { out: T.brands - 0.25 });
  showLine(H.wk.brands, t, T.brands + 0.2, { out: T.back + 0.4 });
  showLine(H.wk.cities, t, T.brands + 0.45, { out: T.back + 0.45 });
}

// 5. The end card: the emblem, his name, the call.
function s5(t) {
  const E = O.em;
  E.g.visible = true;
  const a = expoOut(span(t, T.end - 0.3, T.end + 0.9));
  E.g.position.set(0, lerp(1.6, 0.47, a), lerp(-3, 0, a));
  E.g.quaternion.identity();
  E.g.scale.setScalar(0.62);
  E.coin.rotation.set(0.1 * Math.sin(t * 0.8), Math.PI + lerp(-2.4, 0, a) + 0.25 * Math.sin((t - T.end) * 0.9), 0);
  E.orbit.forEach((r) => (r.visible = true));
  E.burst.forEach((r, i) => {
    const q = span(t, T.hit + i * 0.08, T.hit + 0.8 + i * 0.08);
    r.visible = q > 0 && q < 1;
    r.scale.setScalar(1 + 1.8 * expoOut(q));
    r.material.opacity = (1 - q) * 0.8;
  });
  emblemRings(t, a);
  bloom.strength = 0.7 + 0.6 * pulse(t, T.hit, 4);
  lookAt(V(0, 0.12, 4.2), V(0, 0.12, 0));
  H.end.r.style.display = "block";
  showLine(H.end.name, t, T.end + 0.35);
  showLine(H.end.role, t, T.end + 0.6);
  showLine(H.end.handle, t, T.end + 0.8);
  showLine(H.end.cta, t, T.end + 1.1);
}

window.render = async (t) => {
  const f = Math.round(t * D.fps);
  H.grain.style.backgroundPosition = `${Math.floor(rand(f) * 256)}px ${Math.floor(rand(f + 77) * 256)}px`;
  hideAll();
  if (t < T.drop) s1(t);
  else if (t < T.field) s2(t);
  else if (t < T.work) s3(t);
  else if (t < T.end) s4(t);
  else s5(t);
  if (!(t >= T.field && t < T.dark)) orbs(t, true);
  else orbs(t, false);
  composer.render();
};
